#[derive(Debug, Clone, Copy)]
pub struct RuntimeTimelineStep {
    pub event: &'static str,
    pub after_ms: u64,
    /// JSON object string with ${var} placeholders rendered at dispatch.
    pub payload_json: &'static str,
    /// Raw JSON template; when Some, ${var} placeholders are substituted
    /// directly in the template string BEFORE serde_json::from_str. Lets typed
    /// JSON-value bindings (e.g. array results from @mention_search_results)
    /// splice in as actual arrays/objects rather than string blobs.
    pub payload_template_json: Option<&'static str>,
    /// Multi-event ledger (Pass #33): bindings to insert AFTER this step is rendered.
    /// Subsequent steps see these in their bindings map.
    pub state_seeds_after: &'static [RuntimeStateSeed],
    /// Pass #34: optional single-equality skip primitive. When Some, the step is emitted
    /// only if `bindings[condition.binding] == condition.equals` at dispatch time.
    /// Missing bindings compare against the empty string. No operators, no nesting.
    pub condition: Option<RuntimeStepCondition>,
    /// Pass #35: optional foreach loop primitive. When Some, this step iterates the JSON
    /// array stored in `bindings[foreach.binding]` (set by a state_seed generator that
    /// returns a JSON-encoded array of objects). Body steps execute per-item with
    /// extended bindings: `{as_prefix}.{key}` for each object field plus `{index_var}`
    /// (when non-empty) for the 0-based index. event/payload_json/etc on this step are
    /// ignored when foreach is Some. Single-level iteration only (codegen rejects nesting).
    pub foreach: Option<RuntimeForeach>,
}

#[derive(Debug, Clone, Copy)]
pub struct RuntimeForeach {
    pub binding: &'static str,
    pub as_prefix: &'static str,
    /// Empty string when YAML omits index_var (no index binding emitted per-iter).
    pub index_var: &'static str,
    pub body: &'static [RuntimeTimelineStep],
}

#[derive(Debug, Clone, Copy)]
pub struct RuntimeStateSeed {
    pub var: &'static str,
    /// Either a literal string (used verbatim) or `@generator` (e.g. `@next_shell_id`).
    pub value: &'static str,
}

#[derive(Debug, Clone, Copy)]
pub struct RuntimeStepCondition {
    pub binding: &'static str,
    pub equals: &'static str,
}

#[derive(Debug, Clone, Copy)]
pub struct RuntimeScenarioEntry {
    pub id: &'static str,
    pub input_command: &'static str,
    pub state_seeds: &'static [RuntimeStateSeed],
    pub timeline: &'static [RuntimeTimelineStep],
    /// JSON object string with ${var} placeholders, rendered as the JSON-RPC response.result.
    pub final_response_json: Option<&'static str>,
}

